            rows<<t('Current state, first hit: ','Current state, first hit: ')+forecast_amount(r[:resource],[r[:min],r[:max]])+'; ~'+n(r[:mean].round)+'.'
          end
          rows<<t('Excludes preceding actions; this is not a repeated-action or queued total.','Excludes preceding actions; this is not a repeated-action or queued total.')
        end
